Definition findif_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (r : tokres) (i : nat) (lo : Z) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (vp vl itv fv : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' IT (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' EA (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
    /\ bytes_at bsegs m' SP sbs /\ bytes_at bsegs m' TP tbs
    /\ 0 <= itv < 2^64 /\ 0 <= fv < 2^64
    /\ ex_rem (zbytes tbs) r i (zbytes sbs) = negb ((itv =? SP + Z.of_nat (length sbs)) && (fv =? SP + Z.of_nat (length sbs)))
    /\ ACONST m'.                                                                                          (* [comment removed for export] *)

Definition findif_stmt : Prop :=
  forall (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest rjunk : list cell) (r : tokres) (i : nat) (lo hi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m R rjunk -> cells_size rjunk = 40%nat ->
  rw_cells bsegs m IT (tokit_cells_after r (SP + Z.of_nat i) (SP + Z.of_nat (length sbs))) ->
  (i <= length sbs)%nat -> (forall k l, r = TK_tok k l -> (i + k + l <= length sbs)%nat /\ (1 <= l)%nat) ->
  rw_cells bsegs m EA (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs))) ->
  rw_cells bsegs m T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest) ->
  bytes_at bsegs m SP sbs -> bytes_at bsegs m TP tbs -> SP + Z.of_nat (length sbs) < 2^64 -> TP + Z.of_nat (length tbs) < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + FINDIF_STACK <= bv_unsigned sp -> aceil <= lo ->
  (* [comment removed for export] *)
  bv_unsigned sp <= EA -> EA + SZ_TOKIT <= R -> R + SZ_TOKIT <= hi -> IT + SZ_TOKIT <= lo ->
  (hi <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo) ->
  (hi <= SP \/ SP + Z.of_nat (length sbs) <= lo) -> (hi <= TP \/ TP + Z.of_nat (length tbs) <= lo) ->
  (IT + SZ_TOKIT <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= IT) ->
  (IT + SZ_TOKIT <= SP \/ SP + Z.of_nat (length sbs) <= IT) -> (IT + SZ_TOKIT <= TP \/ TP + Z.of_nat (length tbs) <= IT) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> aobj m IT SZ_TOKIT -> aobj m EA SZ_TOKIT -> aobj m R SZ_TOKIT -> accessible m T 16 -> T mod 8 = 0 ->
  accessible m SP (Z.of_nat (length sbs)) -> accessible m TP (Z.of_nat (length tbs)) ->
  (* [comment removed for export] *)
  0 < IT -> IT mod 8 = 0 -> 0 < EA -> EA mod 8 = 0 ->
  ((0 < length sbs)%nat -> 0 < SP) -> ((0 < length tbs)%nat -> 0 < TP) ->
  evt bsegs (findif_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest r i lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz IT) (wz EA) (wz T) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_TL_FINDIF) fc None m (seg_rom bsegs)).

End STMT.

