(* [comment removed for export] *)
Definition shz (x : Z) : word := Z_to_bv 64 (Z.shiftr x 3 + 2147450880).

(* [comment removed for export] *)
Definition fi_side (m : mem) (R IT EA T SP TP ns nt : Z) : Prop :=
  ACONST m /\ aobj m IT SZ_TOKIT /\ aobj m EA SZ_TOKIT /\ aobj m R SZ_TOKIT /\ accessible m T 16
  /\ accessible m SP ns /\ accessible m TP nt.

Lemma fi_side_now : forall m m1 R IT EA T SP TP ns nt lo hi,
  fi_side m R IT EA T SP TP ns nt -> munch [(lo, hi); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m1 -> wmono bsegs m m1 -> aceil <= lo ->
  fi_side m1 R IT EA T SP TP ns nt.
Proof.
  intros m m1 R IT EA T SP TP ns nt lo hi (AC & AI & AE & AR & AT & AWS & AWT) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z).
  { apply Forall_cons; [apply awin_stack; exact CEIL|]. apply Forall_cons; [exact (aobj_awin _ _ _ AR)|].
    apply Forall_cons; [exact (aobj_awin _ _ _ AI)| apply Forall_nil]. }
  split; [eapply aconst_transport_awin; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption|].
  split; [eapply aobj_transport; fast_eassumption|].
  split; [eapply acc_transport_awin; fast_eassumption|].
  split; eapply acc_transport_awin; fast_eassumption.
Qed.

(* [comment removed for export] *)
Definition fi_frame (j8 : list byte) (R IT EA T : Z) (SV : list cell) : list cell :=
  CB 8 j8 :: C8 (shz (IT + 32)) :: C8 (shz (EA + 32)) :: C8 (wz (IT + 32)) :: C8 (wz (EA + 32))
  :: C8 (shz (IT + 24)) :: C8 (shz (EA + 24)) :: C8 (wz (IT + 24)) :: C8 (wz (EA + 24)) :: C8 (wz R)
  :: C8 (shz T) :: C8 (shz IT) :: C8 (wz IT) :: SV.

(* [comment removed for export] *)
Definition fi_regs (rax spv gp tp t0v t2 a0 a1 a2 a4 a5 a6 a7 s2v s6v t3 t4 t6v : word) (IT EA T : Z) :=
  mkR rax spv gp tp t0v (shz (EA + 16)) t2 (wz 2) (shz (IT + 8)) a0 a1 a2 (wz T) a4 a5 a6 a7
      s2v (shz (T + 8)) (wz (EA + 16)) (shz (IT + 16)) s6v (wz ASHADOW_BASE) (Z_to_bv 64 (-1)) (wz (IT + 16)) (wz (T + 8)) (wz 1)
      t3 t4 (wz (IT + 8)) t6v.

(* [comment removed for export] *)
Definition fi_post_r (vp vl itv fv : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' IT (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' EA (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
    /\ rw_cells bsegs m' T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
    /\ bytes_at bsegs m' SP sbs /\ bytes_at bsegs m' TP tbs
    /\ ACONST m'.

Definition fi_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists vp vl itv fv,
    fi_post_r vp vl itv fv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest lo m ms'
    /\ 0 <= itv < 2^64 /\ 0 <= fv < 2^64
    /\ v = negb ((itv =? SP + Z.of_nat (length sbs)) && (fv =? SP + Z.of_nat (length sbs))).

Lemma fi_post_v_findif : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest r i lo m ms,
  fi_post_v (ex_rem (zbytes tbs) r i (zbytes sbs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest lo m ms ->
  findif_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest r i lo m ms.
Proof.
  intros until ms. intros (vp & vl & itv & fv & PO & HI & HF & FF). unfold fi_post_r in PO. unfold findif_post.
  destruct PO as (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m' & E & MU & WM & MI & ST & RR & ITC & EAC & TC & WS & WT & AC).
  exists t0, t1, t2, a0, a1, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m', vp, vl, itv, fv.
  repeat match goal with |- _ /\ _ => split end; first [assumption | lia].
Qed.

(* [comment removed for export] *)
Definition fi_ctx (m m1 : mem) (sp : word) (SV : list cell) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell)
    (lo : Z) (junkR j8 : list byte) (itc : list cell) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -208) (fi_frame j8 R IT EA T SV)
  /\ rw_cells bsegs m1 R [CB 40 junkR]
  /\ rw_cells bsegs m1 IT itc
  /\ rw_cells bsegs m1 EA (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
  /\ rw_cells bsegs m1 T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at bsegs m1 SP sbs /\ bytes_at bsegs m1 TP tbs
  /\ stk bsegs m1 lo (bv_unsigned sp + -208)
  /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ fi_side m R IT EA T SP TP (Z.of_nat (length sbs)) (Z.of_nat (length tbs)).

Definition fi_pure (sp : word) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo hi : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ TP + Z.of_nat (length tbs) < 2^64
  /\ lo + FINDIF_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ bv_unsigned sp <= EA /\ EA + SZ_TOKIT <= R /\ R + SZ_TOKIT <= hi /\ IT + SZ_TOKIT <= lo
  /\ (hi <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo)
  /\ (hi <= SP \/ SP + Z.of_nat (length sbs) <= lo) /\ (hi <= TP \/ TP + Z.of_nat (length tbs) <= lo)
  /\ (IT + SZ_TOKIT <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= IT)
  /\ (IT + SZ_TOKIT <= SP \/ SP + Z.of_nat (length sbs) <= IT) /\ (IT + SZ_TOKIT <= TP \/ TP + Z.of_nat (length tbs) <= IT)
  /\ ((0 < length sbs)%nat -> 0 < SP) /\ ((0 < length tbs)%nat -> 0 < TP)
  /\ 0 < IT /\ IT mod 8 = 0 /\ 0 < EA /\ EA mod 8 = 0 /\ T mod 8 = 0.

End FI.

Local Ltac open_fctx CTX PURE :=
  lazymatch type of CTX with fi_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR & RJ & ITC & EAC & TC & WS & WT & ST & MU & WM & MI & SD);
  destruct PURE as (SP64 & TP64 & LO & CEIL & LEA & LR & LHI & LIT & ST_ & SS & STP & DT & DS & DTP & NZS & NZT & ITNZ & ITAL & EANZ & EAAL & TAL);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize Nat.add length] in TCB, ST_, DT;
  pose proof (rw_cells_bound _ _ _ _ RJ) as RB; cbn [cells_size csize Nat.add length] in RB;
  pose proof (rw_cells_bound _ _ _ _ EAC) as EAB; cbn [cells_size csize Nat.add length TokItCells] in EAB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & _);
  hydeL ST_; hydeL SS; hydeL STP; hydeL DT; hydeL DS; hydeL DTP; hydeL ITAL; hydeL EAAL; hydeL TAL;
  unfold TokItCells, SZ_TOKIT, FINDIF_STACK, TOKIT_STACK, AINTRIN_STACK, AAPP_HI, fi_frame, tk_saved, shz in *; unfold wz in * end.

Local Ltac rebuild_fctx m sp R IT EA T SP TP :=
  try match goal with C : fi_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -208) (CB 8 ?j8 :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ :: _ ::
             [C8 ?x11; C8 ?x10; C8 ?x9; C8 ?x8; C8 ?x7; C8 ?x6; C8 ?x5; C8 ?x4; C8 ?x3; C8 ?x2; C8 ?x1; C8 ?x0; C8 ?xra]),
    RJ : rw_cells _ mx R [CB 40 ?junkR], ITC : rw_cells _ mx IT ?itc, EAC : rw_cells _ mx EA _,
    TC : rw_cells _ mx T (C8 _ :: C8 (Z_to_bv 64 (Z.of_nat (length ?tbs))) :: ?trest),
    WS : bytes_at _ mx SP ?sbs, WT : bytes_at _ mx TP _, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx, SD : fi_side m _ _ _ _ _ _ _ _ |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : fi_ctx m mx sp (tk_saved x11 x10 x9 x8 x7 x6 x5 x4 x3 x2 x1 x0 xra) R IT EA T SP TP sbs tbs trest lo junkR j8 itc)
        by (unfold fi_ctx, fi_frame, tk_saved, shz, wz; repeat (split; [fast_eassumption|]); fast_eassumption)
  end end.


