Lemma fi_done_v : forall (v : bool) (vp vl itv fv : Z) rax a0x a1x a2x a4x a5x a6x a7x s2x s6x t0x t2 t3 t4
    ra sp gp tp s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v
    (F : bvmap 5 word) fc (m m1 : mem) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo hi : Z) (junkR j8 : list byte),
  fi_ctx m m1 sp (tk_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) R IT EA T SP TP sbs tbs trest lo junkR j8
         (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs))) ->
  fi_pure sp R IT EA T SP TP sbs tbs trest lo hi ->
  0 <= itv < 2^64 -> 0 <= fv < 2^64 -> v = negb ((itv =? SP + Z.of_nat (length sbs)) && (fv =? SP + Z.of_nat (length sbs))) ->
  evt bsegs (fi_post_v v ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc R IT EA T SP TP sbs tbs trest lo m)
    (MS (fi_regs rax (Z_to_bv 64 (bv_unsigned sp + -208)) gp tp t0x t2 a0x a1x a2x a4x a5x a6x a7x s2x s6x t3 t4 (wz IT) IT EA T)
        F (Z_to_bv 64 0xbf8b0) fc None m1 (seg_rom bsegs)).
Proof.
  intros until j8. intros CTX PURE HI HF HV.
  eapply evt_mono; [eapply fi_done; [exact CTX | exact PURE] |].
  intros ms' PO. exists vp, vl, itv, fv. split; [exact PO | split; [exact HI | split; [exact HF | exact HV]]].
Qed.

