    (F : bvmap 5 word) fc (m1 : mem) : Prop :=
  forall t0' a0' a1' a2' a4' a5' a6' a7',
    evt bsegs Q (MS (fi_regs rax spx gp tp t0' t2 a0' a1' a2' a4' a5' a6' a7' s2v s6v t3 t4 t6v IT EA T)
                    F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).
