Lemma fi_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t2 a0 a1 a6 a7 s2v s6v t3 t4 t6v (IT EA T : Z)
    (F : bvmap 5 word) fc (m1 : mem) (TP VP : Z) (tbs vbs : list byte),
  (length tbs - j = k)%nat -> (j < length tbs)%nat -> length vbs = length tbs ->
  bytes_at bsegs m1 TP tbs -> bytes_at bsegs m1 VP vbs -> TP + Z.of_nat (length tbs) < 2^64 -> VP + Z.of_nat (length vbs) < 2^64 ->
  accessible m1 TP (Z.of_nat (length tbs)) -> accessible m1 VP (Z.of_nat (length vbs)) ->
  mem_inv bsegs m1 -> 0 <= IT -> 0 <= EA -> 0 <= T ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = true ->
     fi_cont Q 0xbf8b0 rax spx gp tp t2 s2v s6v t3 t4 t6v IT EA T F fc m1) ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = false ->
     fi_cont Q 0xbf880 rax spx gp tp t2 s2v s6v t3 t4 t6v IT EA T F fc m1) ->
  evt bsegs Q (MS (fi_regs rax spx gp tp (wz VP) t2 a0 a1 (wz (Z.of_nat (length tbs))) (wz TP) (wz (Z.of_nat j)) a6 a7 s2v s6v t3 t4 t6v IT EA T)
